package kr.blackwiki.smp;

import com.google.gson.*;
import org.junit.jupiter.api.*;
import java.net.URI;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import static org.junit.jupiter.api.Assertions.*;

class DiscordGatewayTest {
    @BeforeEach void resetIdentifyWindow()throws Exception{var f=DiscordGateway.class.getDeclaredField("IDENTIFY_AFTER");f.setAccessible(true);((AtomicLong)f.get(null)).set(0);}
    static class Socket implements DiscordGateway.Link{List<JsonObject> sent=new CopyOnWriteArrayList<>();boolean aborted;public CompletionStage<?> send(String text){sent.add(JsonParser.parseString(text).getAsJsonObject());return CompletableFuture.completedFuture(null);}public void abort(){aborted=true;}JsonObject opcode(int code){return sent.stream().filter(j->j.get("op").getAsInt()==code).findFirst().orElse(null);}}
    static class Connector implements DiscordGateway.Connector{List<DiscordGateway.Sink> sinks=new CopyOnWriteArrayList<>();List<Socket> sockets=new CopyOnWriteArrayList<>();public void connect(URI uri,DiscordGateway.Sink sink){Socket s=new Socket();sockets.add(s);sinks.add(sink);sink.opened(s);}void hello(int index)throws Exception{sinks.get(index).text("{\"op\":10,\"d\":{\"heartbeat_interval\":300000}}");} }
    DiscordGateway make(Connector c,List<JsonObject> messages){return new DiscordGateway("unit-test-token-123456789",messages::add,c,()->URI.create("wss://gateway.discord.gg/?v=10&encoding=json"));}
    void hello(DiscordGateway g,Connector c,int index)throws Exception{c.hello(index);var f=DiscordGateway.class.getDeclaredField("heartbeat");f.setAccessible(true);((Future<?>)f.get(g)).cancel(false);}
    void ready(Connector c,int i){c.sinks.get(i).text("{\"op\":0,\"s\":42,\"t\":\"READY\",\"d\":{\"session_id\":\"session-one\",\"resume_gateway_url\":\"wss://gateway-us-east1-b.discord.gg\",\"user\":{\"id\":\"888888888888888888\"}}}");}
    @Test void helloIdentifiesWithMessageContentAndGuildMessageIntents()throws Exception{Connector c=new Connector();try(var g=make(c,new ArrayList<>())){g.start();ControlApiTest.await(()->!c.sockets.isEmpty());hello(g,c,0);ControlApiTest.await(()->c.sockets.getFirst().opcode(2)!=null);JsonObject d=c.sockets.getFirst().opcode(2).getAsJsonObject("d");assertEquals(33281,d.get("intents").getAsInt());ready(c,0);assertTrue(g.ready());assertEquals("888888888888888888",g.botId());}}
    @Test void heartbeatTracksSequenceAndMissingAckReconnects()throws Exception{Connector c=new Connector();try(var g=make(c,new ArrayList<>())){g.start();ControlApiTest.await(()->!c.sockets.isEmpty());hello(g,c,0);ready(c,0);c.sinks.getFirst().text("{\"op\":11}");g.heartbeatNow();assertEquals(42,c.sockets.getFirst().sent.getLast().get("d").getAsLong());c.sinks.getFirst().text("{\"op\":11}");g.heartbeatNow();assertFalse(c.sockets.getFirst().aborted);g.heartbeatNow();assertTrue(c.sockets.getFirst().aborted);assertFalse(g.ready());}}
    @Test void reconnectResumesSessionAndIgnoresStaleSocketMessages()throws Exception{Connector c=new Connector();List<JsonObject> got=new CopyOnWriteArrayList<>();try(var g=make(c,got)){g.start();ControlApiTest.await(()->!c.sockets.isEmpty());hello(g,c,0);ready(c,0);c.sinks.getFirst().text("{\"op\":7,\"d\":null}");ControlApiTest.await(()->c.sockets.size()==2);hello(g,c,1);assertEquals("session-one",c.sockets.get(1).opcode(6).getAsJsonObject("d").get("session_id").getAsString());c.sinks.getFirst().text("{\"op\":0,\"s\":43,\"t\":\"MESSAGE_CREATE\",\"d\":{}}");assertTrue(got.isEmpty());c.sinks.get(1).text("{\"op\":0,\"s\":44,\"t\":\"RESUMED\",\"d\":{}}");assertTrue(g.ready());c.sinks.get(1).text("{\"op\":0,\"s\":45,\"t\":\"MESSAGE_CREATE\",\"d\":{\"content\":\"안녕\"}}");assertEquals(1,got.size());}}
    @Test void privilegedIntentAndBadTokenCloseAreFatalWithoutRetryFlood()throws Exception{for(int code:new int[]{4014,4004}){Connector c=new Connector();try(var g=make(c,new ArrayList<>())){g.start();ControlApiTest.await(()->!c.sockets.isEmpty());c.sinks.getFirst().closed(code);assertTrue(g.fatal());assertFalse(g.ready());g.start();assertEquals(1,c.sockets.size());assertTrue(g.status().contains(code==4014?"Intent":"인증"));}}}
    @Test void duplicateStartCannotOpenTwoConnectionsDuringDiscovery()throws Exception{Connector c=new Connector();CountDownLatch entered=new CountDownLatch(1),release=new CountDownLatch(1);AtomicInteger discoveries=new AtomicInteger();try(var g=new DiscordGateway("unit-test-token-123456789",j->{},c,()->{discoveries.incrementAndGet();entered.countDown();release.await();return URI.create("wss://gateway.discord.gg");})){g.start();assertTrue(entered.await(2,TimeUnit.SECONDS));g.start();g.start();release.countDown();ControlApiTest.await(()->!c.sockets.isEmpty());assertEquals(1,discoveries.get());assertEquals(1,c.sockets.size());}}
    @Test void gatewayUrlCannotRedirectCredentialsToAnotherHost(){for(String s:List.of("ws://gateway.discord.gg","wss://discord.gg.evil.test","wss://gateway.discord.gg@evil.test","wss://localhost","wss://gateway.discord.gg:4433"))assertThrows(IllegalArgumentException.class,()->DiscordGateway.gatewayUri(s));assertEquals("gateway-us-east1-b.discord.gg",DiscordGateway.gatewayUri("wss://gateway-us-east1-b.discord.gg/?z=1").getHost());}
    @Test void closingGatewayAbortsConnectionAndSuppressesLateDispatch()throws Exception{Connector c=new Connector();List<JsonObject> got=new ArrayList<>();var g=make(c,got);g.start();ControlApiTest.await(()->!c.sockets.isEmpty());g.close();assertTrue(c.sockets.getFirst().aborted);c.sinks.getFirst().text("{\"op\":0,\"s\":1,\"t\":\"MESSAGE_CREATE\",\"d\":{}}");assertTrue(got.isEmpty());assertFalse(g.ready());}
}
